import * as THREE from 'three';

window.addEventListener('error',e=>{window.__err=String(e.message||e);});
const _ce=console.error; console.error=(...a)=>{window.__err=a.map(String).join(' ');_ce(...a);};

/* ============================== UTILS ============================== */
const $=id=>document.getElementById(id);
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lerp=(a,b,t)=>a+(b-a)*t;
const damp=(a,b,l,dt)=>lerp(a,b,1-Math.exp(-l*dt));
const sstep=(a,b,x)=>{const t=clamp((x-a)/(b-a),0,1);return t*t*(3-2*t);};
const easeOutCubic=t=>1-Math.pow(1-t,3);
const rand=(a=1,b)=>b===undefined?Math.random()*a:a+Math.random()*(b-a);
const rs=s=>(Math.random()*2-1)*s;
const TAU=Math.PI*2;
const UP=new THREE.Vector3(0,1,0);
const Q0=new THREE.Quaternion();
const ZAXIS=new THREE.Vector3(0,0,1);
const TV1=new THREE.Vector3(),TV2=new THREE.Vector3(),TV3=new THREE.Vector3(),TV4=new THREE.Vector3(),TV5=new THREE.Vector3(),TV6=new THREE.Vector3(),TV7=new THREE.Vector3();

class Spring{
  constructor(stiff=120,dampF=14){this.v=0;this.vel=0;this.stiff=stiff;this.damp=dampF;this.target=0;}
  update(dt){
    dt=Math.min(dt,1/30);
    const a=(this.target-this.v)*this.stiff-this.vel*this.damp;
    this.vel+=a*dt; this.v+=this.vel*dt; return this.v;
  }
}
const lsGet=(k,d)=>{try{const v=localStorage.getItem(k);return v===null?d:v;}catch(e){return d;}};
const lsSet=(k,v)=>{try{localStorage.setItem(k,String(v));}catch(e){}};

/* ============================== AUDIO ============================== */
class SFX{
  init(){
    if(this.ctx)return;
    const AC=window.AudioContext||window.webkitAudioContext;
    this.ctx=new AC();
    this.master=this.ctx.createGain(); this.master.gain.value=0.85;
    this.comp=this.ctx.createDynamicsCompressor();
    this.comp.threshold.value=-16; this.comp.knee.value=22; this.comp.ratio.value=9;
    this.comp.attack.value=0.002; this.comp.release.value=0.22;
    this.master.connect(this.comp); this.comp.connect(this.ctx.destination);
    const len=this.ctx.sampleRate*2, buf=this.ctx.createBuffer(1,len,this.ctx.sampleRate), d=buf.getChannelData(0);
    for(let i=0;i<len;i++)d[i]=Math.random()*2-1;
    this.noiseBuf=buf;
    // urban echo bus
    this.echo=this.ctx.createGain(); this.echo.gain.value=1;
    const dl=this.ctx.createDelay(0.6); dl.delayTime.value=0.26;
    const fb=this.ctx.createGain(); fb.gain.value=0.33;
    const lp=this.ctx.createBiquadFilter(); lp.type='lowpass'; lp.frequency.value=1300;
    this.echo.connect(dl); dl.connect(fb); fb.connect(lp); lp.connect(dl); dl.connect(this.master); this.echo.connect(this.master);
    this.ambience();
  }
  resume(){ if(this.ctx&&this.ctx.state==='suspended')this.ctx.resume(); }
  suspend(){ if(this.ctx&&this.ctx.state==='running')this.ctx.suspend(); }
  ambience(){
    const src=this.ctx.createBufferSource(); src.buffer=this.noiseBuf; src.loop=true;
    const f=this.ctx.createBiquadFilter(); f.type='lowpass'; f.frequency.value=260;
    const g=this.ctx.createGain(); g.gain.value=0.05;
    const lfo=this.ctx.createOscillator(); lfo.frequency.value=0.09;
    const lg=this.ctx.createGain(); lg.gain.value=0.022;
    lfo.connect(lg); lg.connect(g.gain);
    src.connect(f); f.connect(g); g.connect(this.master);
    src.start(); lfo.start();
    const r=this.ctx.createBufferSource(); r.buffer=this.noiseBuf; r.loop=true; r.playbackRate.value=0.4;
    const rf=this.ctx.createBiquadFilter(); rf.type='lowpass'; rf.frequency.value=90;
    const rg=this.ctx.createGain(); rg.gain.value=0.05;
    r.connect(rf); rf.connect(rg); rg.connect(this.master); r.start();
    this.ambNodes=[{src,rate:1,f,f0:260},{src:r,rate:0.4,f:rf,f0:90}];
  }
  _n(o){
    if(!this.ctx)return;
    const t0=this.ctx.currentTime+(o.when||0);
    const src=this.ctx.createBufferSource(); src.buffer=this.noiseBuf;
    src.playbackRate.value=(o.rate||1)*this._pk();
    const f=this.ctx.createBiquadFilter(); f.type=o.type||'bandpass'; f.frequency.value=(o.f||1000)*this._pk(); f.Q.value=o.q||1;
    const g=this.ctx.createGain();
    const atk=o.atk||0.001, rel=o.rel||0.1, gg=o.g||0.4;
    g.gain.setValueAtTime(0.0001,t0);
    g.gain.linearRampToValueAtTime(gg,t0+atk);
    g.gain.exponentialRampToValueAtTime(0.0001,t0+atk+rel);
    src.connect(f); f.connect(g); g.connect(o.bus||this.master);
    src.start(t0); src.stop(t0+atk+rel+0.05);
  }
  _t(o){
    if(!this.ctx)return;
    const t0=this.ctx.currentTime+(o.when||0);
    const osc=this.ctx.createOscillator(); osc.type=o.type||'sine';
    const pk=this._pk();
    osc.frequency.setValueAtTime((o.f||440)*pk,t0);
    if(o.f2)osc.frequency.exponentialRampToValueAtTime(Math.max(o.f2*pk,1),t0+(o.dur||0.2));
    const g=this.ctx.createGain();
    const atk=o.atk||0.002, dur=o.dur||0.2;
    g.gain.setValueAtTime(0.0001,t0);
    g.gain.linearRampToValueAtTime(o.g||0.3,t0+atk);
    g.gain.exponentialRampToValueAtTime(0.0001,t0+dur);
    osc.connect(g); g.connect(o.bus||this.master);
    osc.start(t0); osc.stop(t0+dur+0.05);
  }
  shot(){
    const r=rand(0.92,1.08);
    this._n({f:3400*r,q:0.7,type:'highpass',g:0.5,rel:0.026});
    this._n({f:1150*r,q:0.8,g:0.5,rel:0.07});
    this._t({f:150*r,f2:42,dur:0.1,g:0.9});
    this._n({f:700,q:0.5,type:'lowpass',g:0.3,rel:0.3,when:0.012,rate:0.8});
    this._n({f:520,q:2,g:0.13,rel:0.42,when:0.07,rate:0.7,bus:this.echo});
    this._t({f:2500+rand(-300,300),dur:0.02,type:'square',g:0.04});
  }
  enemyShot(dist){
    const v=clamp(1-dist/75,0.18,0.85);
    this._n({f:850,q:0.7,type:'lowpass',g:0.38*v,rel:0.09,rate:rand(0.85,1.05)});
    this._t({f:115,f2:44,dur:0.14,g:0.5*v});
    this._n({f:600,q:0.5,type:'lowpass',g:0.18*v,rel:0.38,when:0.02,bus:this.echo});
  }
  snap(){ this._n({f:6200,q:1,type:'highpass',g:0.3,rel:0.03}); this._t({f:900,f2:320,dur:0.03,type:'triangle',g:0.12}); }
  hitBody(){ this._t({f:215,f2:120,dur:0.07,type:'triangle',g:0.45}); this._n({f:1400,q:2,g:0.22,rel:0.035}); }
  hitHead(){ this._t({f:1250,dur:0.17,g:0.35}); this._t({f:1870,dur:0.11,g:0.13,when:0.01}); this._n({f:3200,q:3,g:0.16,rel:0.04}); }
  kill(){ this._t({f:660,dur:0.08,type:'square',g:0.13}); this._t({f:880,dur:0.13,type:'square',g:0.13,when:0.07}); }
  dry(){ this._n({f:2600,q:4,g:0.22,rel:0.02}); this._t({f:1500,dur:0.02,type:'square',g:0.05}); }
  pistol(){
    this._n({f:4200,q:0.7,type:'highpass',g:0.42,rel:0.02});
    this._n({f:1500,q:0.9,g:0.4,rel:0.05});
    this._t({f:185,f2:55,dur:0.07,g:0.7});
    this._n({f:800,q:0.6,type:'lowpass',g:0.2,rel:0.18,when:0.01,bus:this.echo});
  }
  boom(){
    this._n({f:420,q:0.4,type:'lowpass',g:0.85,rel:0.22,rate:0.7});
    this._t({f:75,f2:26,dur:0.42,g:1.0});
    this._n({f:2600,q:0.7,type:'highpass',g:0.3,rel:0.03});
    this._n({f:300,q:0.5,type:'lowpass',g:0.4,rel:0.7,when:0.03,bus:this.echo});
  }
  pump(){
    this._n({f:1100,q:3,g:0.3,rel:0.035});
    this._n({f:750,q:2.5,g:0.32,rel:0.045,when:0.1});
    this._t({f:260,f2:160,dur:0.05,g:0.16,when:0.1});
  }
  wswitch(i){
    if(i===1){ this._n({f:2300,q:3,g:0.22,rel:0.025}); this._t({f:520,f2:340,dur:0.05,g:0.12,when:0.03}); }
    else if(i===2){ this._n({f:1500,q:2.5,g:0.24,rel:0.03}); this._n({f:950,q:2,g:0.26,rel:0.045,when:0.05}); }
    else { this._n({f:1900,q:3,g:0.26,rel:0.03}); this._n({f:1200,q:2,g:0.28,rel:0.04,when:0.06}); this._t({f:420,f2:280,dur:0.05,g:0.14,when:0.06}); }
  }
  reloadClack(n){
    if(n===1){ this._n({f:1900,q:3,g:0.35,rel:0.03}); this._n({f:900,q:2,g:0.28,rel:0.05,when:0.02}); }
    else if(n===2){ this._n({f:1600,q:3,g:0.4,rel:0.035}); this._t({f:300,f2:150,dur:0.06,g:0.4}); }
    else { this._n({f:2200,q:4,g:0.3,rel:0.025}); this._n({f:2400,q:4,g:0.3,rel:0.025,when:0.07}); this._t({f:400,f2:250,dur:0.05,g:0.2,when:0.07}); }
  }
  footstep(run){ this._n({f:420+rand(-60,60),q:0.8,type:'lowpass',g:run?0.2:0.12,rel:0.055,rate:rand(0.9,1.1)}); this._t({f:95,f2:60,dur:0.05,g:0.1}); }
  land(v){ const k=clamp(v*0.09,0.1,0.5); this._t({f:190,f2:55,dur:0.12,g:k}); this._n({f:500,q:0.6,type:'lowpass',g:k*0.6,rel:0.09}); }
  hurt(){ this._t({f:130,f2:70,dur:0.18,g:0.45}); this._n({f:420,q:1,type:'lowpass',g:0.28,rel:0.1}); }
  waveClear(){ this._t({f:520,dur:0.12,g:0.18}); this._t({f:780,dur:0.22,g:0.18,when:0.12}); }
  waveStart(){ this._t({f:340,dur:0.14,type:'square',g:0.1}); this._t({f:510,dur:0.14,type:'square',g:0.1,when:0.16}); }
  death(){ this._t({f:220,f2:52,dur:1.3,type:'sawtooth',g:0.25}); this._n({f:300,q:0.5,type:'lowpass',g:0.3,rel:1.2}); }
  jump(){ this._n({f:600,q:1,type:'lowpass',g:0.08,rel:0.06}); }
  _pk(){ return lerp(1,0.55,this.slowK||0); }
  setSlow(k){
    this.slowK=k||0;
    if(!this.ambNodes)return;
    const pk=this._pk();
    for(const a of this.ambNodes){
      a.src.playbackRate.value=a.rate*pk;
      a.f.frequency.value=a.f0*pk;
    }
  }
  whoosh(dirIn){
    if(!this.ctx)return;
    const t0=this.ctx.currentTime;
    const src=this.ctx.createBufferSource(); src.buffer=this.noiseBuf; src.loop=true;
    const f=this.ctx.createBiquadFilter(); f.type='bandpass'; f.Q.value=1.1;
    const g=this.ctx.createGain();
    f.frequency.setValueAtTime(dirIn?260:1500,t0);
    f.frequency.exponentialRampToValueAtTime(dirIn?1500:260,t0+0.3);
    g.gain.setValueAtTime(0.0001,t0);
    g.gain.linearRampToValueAtTime(dirIn?0.42:0.3,t0+0.05);
    g.gain.exponentialRampToValueAtTime(0.0001,t0+0.34);
    src.connect(f); f.connect(g); g.connect(this.master);
    src.start(t0); src.stop(t0+0.4);
    this._t({f:dirIn?130:55,f2:dirIn?55:130,dur:0.32,type:'sine',g:0.26});
  }
}
const sfx=new SFX();

/* ============================== RENDERER / SCENES ============================== */
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});
renderer.setSize(innerWidth,innerHeight);
const MAXDPR=Math.min(devicePixelRatio||1,2);
renderer.setPixelRatio(MAXDPR);
renderer.toneMapping=THREE.NoToneMapping;
renderer.toneMappingExposure=2.2;
renderer.shadowMap.enabled=true;
renderer.shadowMap.type=THREE.PCFSoftShadowMap;
renderer.autoClear=false;
document.body.appendChild(renderer.domElement);
const canvas=renderer.domElement;

const scene=new THREE.Scene();
scene.fog=new THREE.Fog(0x33283a,38,190);
const camera=new THREE.PerspectiveCamera(75,innerWidth/innerHeight,0.08,320);
camera.rotation.order='YXZ';

const vmScene=new THREE.Scene();
const vmCam=new THREE.PerspectiveCamera(55,innerWidth/innerHeight,0.01,6);

/* ============================== PROCEDURAL TEXTURES ============================== */
function cnv(w,h,fn){
  const c=document.createElement('canvas'); c.width=w; c.height=h;
  fn(c.getContext('2d'),w,h);
  const t=new THREE.CanvasTexture(c);
  t.colorSpace=THREE.SRGBColorSpace;
  t.wrapS=t.wrapT=THREE.RepeatWrapping;
  return t;
}
function noiseOver(ctx,w,h,n,a){
  for(let i=0;i<n;i++){
    const v=Math.random()*255|0;
    ctx.fillStyle=`rgba(${v},${v},${v},${a})`;
    ctx.fillRect(Math.random()*w,Math.random()*h,rand(1,3),rand(1,3));
  }
}
const texConcrete=cnv(512,512,(x,w,h)=>{
  x.fillStyle='#4a4a4d'; x.fillRect(0,0,w,h);
  noiseOver(x,w,h,9000,0.05);
  x.strokeStyle='rgba(0,0,0,0.28)'; x.lineWidth=2;
  for(let i=0;i<=4;i++){ x.beginPath(); x.moveTo(i*128,0); x.lineTo(i*128,h); x.stroke(); x.beginPath(); x.moveTo(0,i*128); x.lineTo(w,i*128); x.stroke(); }
  for(let i=0;i<26;i++){ x.fillStyle=`rgba(20,18,16,${rand(0.03,0.1)})`; x.beginPath(); x.ellipse(Math.random()*w,Math.random()*h,rand(8,60),rand(8,60),rand(TAU),0,TAU); x.fill(); }
});
const texAsphalt=cnv(512,512,(x,w,h)=>{
  x.fillStyle='#26262a'; x.fillRect(0,0,w,h);
  noiseOver(x,w,h,14000,0.06);
  for(let i=0;i<18;i++){
    x.strokeStyle=`rgba(10,10,12,${rand(0.2,0.5)})`; x.lineWidth=1;
    x.beginPath(); let px=Math.random()*w,py=Math.random()*h; x.moveTo(px,py);
    for(let j=0;j<6;j++){ px+=rand(-40,40); py+=rand(-40,40); x.lineTo(px,py); } x.stroke();
  }
  for(let i=0;i<14;i++){ // damp albedo mottling (tile-wrapped)
    const px=Math.random()*w,py=Math.random()*h,rx=rand(14,52),ry=rand(10,40),a=rand(0.04,0.09);
    x.fillStyle=`rgba(8,9,12,${a.toFixed(3)})`;
    for(const oy of [-h,0,h]) for(const ox of [-w,0,w]){ x.beginPath(); x.ellipse(px+ox,py+oy,rx,ry,rand(TAU),0,TAU); x.fill(); }
  }
});
texAsphalt.repeat.set(14,14);
const texRoad=cnv(256,512,(x,w,h)=>{
  x.fillStyle='#232327'; x.fillRect(0,0,w,h);
  noiseOver(x,w,h,5000,0.05);
  x.fillStyle='#8a8455';
  for(let i=0;i<8;i++) x.fillRect(w/2-3,i*64+10,6,34);
  const wg=x.createLinearGradient(0,0,w,0); // wet wheel-track albedo tint
  wg.addColorStop(0,'rgba(0,0,0,0)'); wg.addColorStop(0.16,'rgba(0,0,0,0)');
  wg.addColorStop(0.26,'rgba(4,5,8,0.20)'); wg.addColorStop(0.36,'rgba(0,0,0,0)');
  wg.addColorStop(0.5,'rgba(4,5,8,0.06)');
  wg.addColorStop(0.64,'rgba(0,0,0,0)'); wg.addColorStop(0.74,'rgba(4,5,8,0.20)');
  wg.addColorStop(0.84,'rgba(0,0,0,0)'); wg.addColorStop(1,'rgba(0,0,0,0)');
  x.fillStyle=wg; x.fillRect(0,0,w,h);
  x.strokeStyle='rgba(6,7,10,1)'; x.lineWidth=2;
  for(let i=0;i<12;i++){ // damp streaks along the lane (tile-wrapped)
    x.save(); x.globalAlpha=rand(0.10,0.26);
    for(const oy of [-h,0,h]){
      x.beginPath(); let px=rand(w*0.2,w*0.8),py=oy+rand(-20,20); x.moveTo(px,py);
      for(let j=0;j<5;j++){ py+=rand(60,120); px+=rand(-9,9); x.lineTo(px,py); }
      x.stroke();
    }
    x.restore();
  }
});
const texCrate=cnv(256,256,(x,w,h)=>{
  x.fillStyle='#6e5636'; x.fillRect(0,0,w,h);
  for(let i=0;i<5;i++){ x.fillStyle=i%2?'#66502f':'#755c3b'; x.fillRect(0,i*52,w,50); }
  noiseOver(x,w,h,4000,0.06);
  x.strokeStyle='rgba(30,20,10,0.7)'; x.lineWidth=6; x.strokeRect(3,3,w-6,h-6);
  x.fillStyle='rgba(240,235,220,0.75)'; x.font='bold 34px Arial'; x.textAlign='center';
  x.save(); x.translate(w/2,h/2); x.fillText('7.62 AMMO',0,10); x.restore();
});
function texFacade(litChance){
  return cnv(256,256,(x,w,h)=>{
    x.fillStyle='#3c3a3e'; x.fillRect(0,0,w,h);
    noiseOver(x,w,h,2500,0.05);
    for(let wy=0;wy<2;wy++)for(let wx=0;wx<2;wx++){
      const px=wx*128+34, py=wy*128+26, ww=60, wh=74;
      x.fillStyle='#191b20'; x.fillRect(px-5,py-5,ww+10,wh+10);
      const lit=Math.random()<litChance;
      x.fillStyle=lit?'#ffd9a0':'#232c38';
      x.fillRect(px,py,ww,wh);
      if(!lit){ x.fillStyle='rgba(120,150,190,0.16)'; x.beginPath(); x.moveTo(px,py+wh); x.lineTo(px+ww*0.6,py); x.lineTo(px+ww,py); x.lineTo(px+ww*0.4,py+wh); x.fill(); }
      x.strokeStyle='rgba(0,0,0,0.5)'; x.lineWidth=3;
      x.beginPath(); x.moveTo(px+ww/2,py); x.lineTo(px+ww/2,py+wh); x.moveTo(px,py+wh/2); x.lineTo(px+ww,py+wh/2); x.stroke();
      x.fillStyle='rgba(255,255,255,0.09)'; x.fillRect(px-7,py+wh+5,ww+14,6);
    }
  });
}
const facades=[texFacade(0.14),texFacade(0.22),texFacade(0.3),texFacade(0.1),texFacade(0.26),texFacade(0.18)];
const texBarrier=cnv(256,128,(x,w,h)=>{
  x.fillStyle='#8d8d88'; x.fillRect(0,0,w,h);
  noiseOver(x,w,h,2200,0.07);
  x.fillStyle='rgba(0,0,0,0.25)'; x.fillRect(0,h*0.62,w,10);
  x.fillStyle='rgba(230,120,40,0.5)'; for(let i=0;i<4;i++) x.fillRect(i*64+8,h*0.35,28,10);
});
const texFlash=(()=>{
  const c=document.createElement('canvas'); c.width=c.height=128;
  const x=c.getContext('2d');
  const g=x.createRadialGradient(64,64,2,64,64,62);
  g.addColorStop(0,'rgba(255,255,240,1)'); g.addColorStop(0.25,'rgba(255,214,150,0.9)');
  g.addColorStop(0.55,'rgba(255,140,50,0.35)'); g.addColorStop(1,'rgba(255,120,40,0)');
  x.fillStyle=g; x.fillRect(0,0,128,128);
  x.strokeStyle='rgba(255,230,180,0.85)'; x.lineWidth=5; x.lineCap='round';
  for(let i=0;i<4;i++){ x.save(); x.translate(64,64); x.rotate(i*Math.PI/2+0.4); x.beginPath(); x.moveTo(0,-6); x.lineTo(0,-56); x.stroke(); x.restore(); }
  const t=new THREE.CanvasTexture(c); t.colorSpace=THREE.SRGBColorSpace; return t;
})();
const texDot=(()=>{
  const c=document.createElement('canvas'); c.width=c.height=64;
  const x=c.getContext('2d');
  const g=x.createRadialGradient(32,32,1,32,32,30);
  g.addColorStop(0,'rgba(255,60,40,1)'); g.addColorStop(0.3,'rgba(255,40,30,0.8)'); g.addColorStop(1,'rgba(255,30,20,0)');
  x.fillStyle=g; x.fillRect(0,0,64,64);
  return new THREE.CanvasTexture(c);
})();
/* procedural detail maps (normal + roughness) */
function texData(w,h,fn){
  const c=document.createElement('canvas'); c.width=w; c.height=h;
  fn(c.getContext('2d'),w,h);
  const t=new THREE.CanvasTexture(c);
  t.colorSpace=THREE.NoColorSpace; t.wrapS=t.wrapT=THREE.RepeatWrapping;
  return t;
}
function valueNoise(w,h,scale){
  const gx=(w/scale)|0, gy=(h/scale)|0, grid=new Float32Array((gx+2)*(gy+2));
  for(let i=0;i<grid.length;i++)grid[i]=Math.random();
  const out=new Float32Array(w*h);
