function pSpawn(sys,o){
  let i=sys.cursor;
  for(let k=0;k<sys.count;k++){ const j=(sys.cursor+k)%sys.count; if(sys.life[j]<=0){i=j;break;} }
  sys.cursor=(i+1)%sys.count;
  const k3=i*3;
  sys.pos[k3]=o.x; sys.pos[k3+1]=o.y; sys.pos[k3+2]=o.z;
  sys.vel[k3]=o.vx||0; sys.vel[k3+1]=o.vy||0; sys.vel[k3+2]=o.vz||0;
  sys.life[i]=sys.maxL[i]=o.life;
  sys.siz[i]=o.size; sys.grow[i]=o.grow||0;
  sys.grav[i]=o.grav||0; sys.drag[i]=o.drag||0;
  sys.base[i]=o.alpha!==undefined?o.alpha:1;
  sys.alp[i]=sys.base[i];
  sys.col[k3]=o.r; sys.col[k3+1]=o.g; sys.col[k3+2]=o.b;
}
function pUpdate(sys,dt){
  const {pos,vel,life,maxL,grow,siz,grav,drag,alp,base,count}=sys;
  for(let i=0;i<count;i++){
    if(life[i]<=0)continue;
    life[i]-=dt;
    if(life[i]<=0){ alp[i]=0; pos[i*3+1]=-999; continue; }
    const k=i*3;
    vel[k+1]+=grav[i]*dt;
    const dr=Math.max(0,1-drag[i]*dt);
    vel[k]*=dr; vel[k+1]*=dr; vel[k+2]*=dr;
    pos[k]+=vel[k]*dt; pos[k+1]+=vel[k+1]*dt; pos[k+2]+=vel[k+2]*dt;
    if(pos[k+1]<0.02&&grav[i]<0){ pos[k+1]=0.02; vel[k+1]*=-0.3; }
    siz[i]+=grow[i]*dt;
    alp[i]=base[i]*(life[i]/maxL[i]);
  }
  sys.g.attributes.position.needsUpdate=true;
  sys.g.attributes.aColor.needsUpdate=true;
  sys.g.attributes.aSize.needsUpdate=true;
  sys.g.attributes.aAlpha.needsUpdate=true;
}
