function fireTracer(from,to,speed){
  let tr=null;
  for(const t of tracers)if(!t.on){tr=t;break;}
  if(!tr)return;
  tr.p.copy(from); tr.d.copy(to).sub(from); tr.left=tr.d.length(); tr.d.normalize();
  tr.sp=speed; tr.on=true; tr.m.visible=true;
  tr.m.position.copy(from);
  tr.m.quaternion.setFromUnitVectors(ZAXIS,tr.d);
  const bz=Math.min(2.6,tr.left*0.5+0.4); tr.bz=bz; tr.m.scale.set(1,1,bz);
}
function updateTracers(dt){
  tracerMat.opacity=Math.min(1,0.9+0.3*SM.k);
  const str=1+SM.k;
  for(const t of tracers){
    if(!t.on)continue;
    const step=t.sp*dt;
    if(step>=t.left){ t.on=false; t.m.visible=false; continue; }
    t.p.addScaledVector(t.d,step); t.left-=step;
    t.m.position.copy(t.p);
    t.m.scale.z=t.bz*str;
  }
}
