  }
}
const dproj=new THREE.Vector3();
function dmgNum(pos,text,cls){
  let d=null;
  for(const k of dmgPool)if(!k.on){d=k;break;}
  if(!d)return;
  d.on=true; d.life=0; d.max=0.85; d.vy=rand(0.8,1.3);
  d.wp.copy(pos); d.wp.x+=rs(0.15); d.wp.y+=rand(0.1,0.3);
  d.el.textContent=text; d.el.className='dnum'+(cls?' '+cls:'');
}
function updateDmgNums(dt){
  for(const d of dmgPool){
    if(!d.on)continue;
    d.life+=dt; d.wp.y+=d.vy*dt;
    if(d.life>=d.max){ d.on=false; d.el.style.opacity='0'; continue; }
    dproj.copy(d.wp).project(camera);
    if(dproj.z>1){ d.el.style.opacity='0'; continue; }
    const x=(dproj.x*0.5+0.5)*innerWidth, y=(-dproj.y*0.5+0.5)*innerHeight;
    const t=d.life/d.max;
    d.el.style.opacity=String(t<0.15?t/0.15:1-Math.max(0,(t-0.5)/0.5));
    d.el.style.transform=`translate(-50%,-50%) translate(${x.toFixed(1)}px,${y.toFixed(1)}px) scale(${(0.8+t*0.4).toFixed(2)})`;
  }
}
