  }
}
function addHitDir(fromPos){
  const bearing=Math.atan2(fromPos.x-P.pos.x,-(fromPos.z-P.pos.z));
  let h=null;
  for(const k of hitDirs)if(!k.on){h=k;break;}
  if(!h)return;
  h.on=true; h.life=1; h.ang=bearing;
}
function updateHitDirs(dt,heading){
  for(const h of hitDirs){
    if(!h.on)continue;
    h.life-=dt*1.1;
    if(h.life<=0){ h.on=false; h.el.style.opacity='0'; continue; }
    const rel=(h.ang-heading)*180/Math.PI;
    h.el.style.opacity=String(Math.min(1,h.life*2));
    h.el.style.transform=`translate(-50%,-50%) rotate(${rel.toFixed(1)}deg)`;
  }
}
