function checkLOS(from,to){
  TV6.copy(to).sub(from);
  const d=TV6.length();
  if(d<0.5)return true;
  TV6.multiplyScalar(1/d);
  losRay.set(from,TV6);
  losRay.far=d-0.4;
  return losRay.intersectObjects(solidMeshes,false).length===0;
}

let shootTargets=[];
