}

class Enemy{
  constructor(){
    this.root=new THREE.Group();
    this.yawG=new THREE.Group(); this.root.add(this.yawG);
    this.body=new THREE.Group(); this.yawG.add(this.body);
    this.mFat=eBase.fat.clone(); this.mVest=eBase.vest.clone(); this.mPouch=eBase.pouch.clone();
    this.mDark=eBase.dark.clone(); this.mHelm=eBase.helm.clone(); this.mBoot=eBase.boot.clone(); this.mGun=eBase.gun.clone();
    this.mVisor=eBase.visor.clone(); this.mPauldron=eBase.pauldron.clone();
    this.mats=[this.mFat,this.mVest,this.mPouch,this.mDark,this.mHelm,this.mBoot,this.mGun,this.mVisor,this.mPauldron];
    this.hitMeshes=[];
    this.pos=this.root.position;
    this.build();
    this.root.visible=false;
    scene.add(this.root);
    this.active=false; this.dead=false;
  }
  mk(geo,mat,x,y,z,part,parent){
    const m=new THREE.Mesh(geo,mat);
    m.position.set(x,y,z); m.castShadow=true;
    m.userData={en:this,part};
    (parent||this.body).add(m);
    if(part)this.hitMeshes.push(m);
    return m;
  }
  build(){
    const b=this.body;
    this.mk(EG.pelvis,this.mFat,0,0.86,0,'body');
    this.mk(EG.torso,this.mFat,0,1.10,0,'body');
    this.mk(EG.vest,this.mVest,0,1.08,0.01,'body');
    for(let i=-1;i<=1;i++)this.mk(EG.pouch,this.mPouch,i*0.12,1.0,0.155,'body');
    this.mk(EG.pack,this.mPouch,0,1.14,-0.19,'body');
    this.mk(EG.head,this.mDark,0,1.49,0,'head');
    this.mk(EG.helmet,this.mHelm,0,1.525,0,'head');
    this.mk(EG.nvg,this.mDark,0,1.50,-0.13,'head');
    this.mk(EG.visor,this.mVisor,0,1.505,-0.155,'head');
    this.mk(EG.pauldron,this.mPauldron,-0.27,1.40,0,'body');
    this.mk(EG.pauldron,this.mPauldron,0.27,1.40,0,'body');
    this.armL=new THREE.Group(); this.armL.position.set(-0.235,1.28,0); b.add(this.armL);
    this.armR=new THREE.Group(); this.armR.position.set(0.235,1.28,0); b.add(this.armR);
    for(const [g,sx] of [[this.armL,-1],[this.armR,1]]){
      this.mk(EG.upArm,this.mFat,0,-0.14,0,'limb',g);
      const fg=new THREE.Group(); fg.position.y=-0.3; g.add(fg);
      this.mk(EG.foreArm,this.mDark,0,-0.13,0,'limb',fg);
      fg.rotation.x=-0.55;
    }
    this.gunPivot=new THREE.Group(); this.gunPivot.position.set(0.05,1.18,-0.16); b.add(this.gunPivot);
    this.mk(EG.gunBody,this.mGun,0,0,-0.05,null,this.gunPivot);
    this.mk(EG.gunMag,this.mGun,0,-0.07,-0.02,null,this.gunPivot).rotation.x=0.15;
    this.mk(EG.gunStock,this.mGun,0,0.005,0.16,null,this.gunPivot);
    const brl=this.mk(EG.gunBarrel,this.mGun,0,0.012,-0.32,null,this.gunPivot);
    brl.rotation.x=Math.PI/2;
    this.muzzleObj=new THREE.Object3D(); this.muzzleObj.position.set(0,0.012,-0.4); this.gunPivot.add(this.muzzleObj);
    this.legL=new THREE.Group(); this.legL.position.set(-0.095,0.80,0); b.add(this.legL);
    this.legR=new THREE.Group(); this.legR.position.set(0.095,0.80,0); b.add(this.legR);
    for(const g of [this.legL,this.legR]){
      this.mk(EG.thigh,this.mFat,0,-0.17,0,'limb',g);
      const sg=new THREE.Group(); sg.position.y=-0.34; g.add(sg);
      this.mk(EG.shin,this.mDark,0,-0.17,0,'limb',sg);
      this.mk(EG.boot,this.mBoot,0,-0.365,-0.04,'limb',sg);
    }
  }
  spawn(x,z){
    this.pos.set(x,0,z);
    this.hp=100+Math.min(30,(S.wave-1)*5);
    this.dead=false; this.active=true;
    this.state='advance'; this.cover=null;
    this.yawG.rotation.y=rand(TAU);
    this.body.position.y=0; this.body.rotation.set(0,0,0);
    this.root.quaternion.identity();
    this.walkPh=rand(TAU); this.moveAmt=0;
    this.losT=rand(0.2); this.hasLOS=false; this.lostT=0;
    this.peeking=false; this.peekT=rand(0.4,1.4); this.burstLeft=0; this.shotT=0;
    this.strafeOn=false; this.strafeT=rand(0.4,1.0); this.strafeDir=Math.random()<0.5?-1:1;
    this.aim=0; this.crouch=0; this.stuckT=0; this.lastX=x; this.lastZ=z;
    this.deathT=0; this.qTotal=null; this.flingV=null; this.fading=false;
    this.speed=3.1+Math.min(0.9,S.wave*0.09);
    this.reactT=0.6;
    this.root.visible=true;
    for(const m of this.mats){ m.transparent=false; m.opacity=1; m.needsUpdate=true; }
    for(const g of [this.legL,this.legR])g.rotation.set(0,0,0);
    this.armL.rotation.set(0,0,0); this.armR.rotation.set(0,0,0);
