  eyePos(out,h){
    return out.set(this.pos.x,this.pos.y+(h!==undefined?h:(this.crouch>0.5?1.05:1.48)),this.pos.z);
  }
  pickCover(){
    let best=null,bd=1e9;
    for(const cp of coverPts){
      const dp=Math.hypot(cp.x-P.pos.x,cp.z-P.pos.z);
      if(dp<7||dp>30)continue;
      const de=Math.hypot(cp.x-this.pos.x,cp.z-this.pos.z);
      const sc=de+Math.abs(dp-14)*1.5+Math.random()*6;
      if(sc<bd){bd=sc;best=cp;}
    }
    this.cover=best;
  }
  shoot(){
    const mp=this.muzzleObj.getWorldPosition(TV1);
    const eye=TV2.copy(camera.position);
    const d=mp.distanceTo(eye);
    let ch=0.3+Math.min(0.12,S.wave*0.012)+clamp(1.4-d/26,0,0.15);
    if(P.speedXZ>3.5)ch*=0.6;
    if(P.crouch)ch*=0.8;
    const hit=Math.random()<ch;
    TV3.set(rs(1),rs(1)*0.6,rs(1)).multiplyScalar(hit?0.06:rand(0.5,1.6));
    const tgt=TV4.copy(eye).add(TV3);
    TV5.copy(tgt).sub(mp).normalize();
    fireTracer(mp,tgt,170+rand(50));
    worldFlash(mp,rand(0.45,0.7));
    enemyLight.position.copy(mp); enemyLight.intensity=5;
    sfx.enemyShot(d);
    if(hit){
      playerHit(rand(6,12)+S.wave*0.4,this.pos);
    }else{
      if(TV3.length()<1.1&&d<28)sfx.snap();
      losRay.set(mp,TV5); losRay.far=60;
      const hits=losRay.intersectObjects(solidMeshes,false);
      if(hits.length){ emitSparks(hits[0].point,4,0.7); emitDust(hits[0].point); }
    }
  }
  damage(dmg,point,dir,head){
    if(this.dead)return;
    this.hp-=dmg;
    this.shotT+=0.15;
    if(this.hp<=0)this.die(dir,head);
  }
  die(dir,head){
    this.dead=true; this.deathT=0;
    const axis=TV1.copy(dir).cross(UP);
    if(axis.lengthSq()<0.01)axis.set(1,0,0);
    axis.normalize();
    const qFall=new THREE.Quaternion().setFromAxisAngle(axis,-Math.PI/2*rand(0.92,1.05));
    const qSpin=new THREE.Quaternion().setFromAxisAngle(UP,rs(0.7));
    this.qTotal=qSpin.multiply(qFall);
    this.flingV=new THREE.Vector3(dir.x,0,dir.z).multiplyScalar(2.4);
    // splay limbs
    this.armL.rotation.set(rand(-1.4,-0.4),0,rand(-0.6,0.6));
    this.armR.rotation.set(rand(-1.4,-0.4),0,rand(-0.6,0.6));
    this.legL.rotation.x=rand(-0.5,0.5); this.legR.rotation.x=rand(-0.5,0.5);
    this.body.position.y=0;
    emitBlood(TV2.set(this.pos.x,this.pos.y+1.1,this.pos.z),dir,head?18:12);
    emitRing(TV2,rand(1.4,2.0));
    emitSparks(TV2,head?12:7,1.15);
    emitSmoke(TV2,rs(0.4),rand(0.5,1.1),rs(0.4),rand(0.25,0.4),rand(0.9,1.5),0.35,0.33,0.32,0.5);
    flashLight(TV2,head?22:14,0.22);
    fxPulse(head?0.5:0.32);
    const pts=100+(head?50:0);
    S.score+=pts;
    dmgNum(TV2,'+'+pts,'score');
    hitMarker(true);
    sfx.kill();
    S.hitstopT=Math.max(S.hitstopT,0.045); S.hitstopS=0.12;
    if(head)S.slowT=Math.max(S.slowT,0.12);
    saveBest();
    updateScoreHUD();
  }
  updateDeath(dt){
    this.deathT+=dt;
    if(this.flingV){
      this.pos.addScaledVector(this.flingV,dt);
      this.flingV.multiplyScalar(Math.max(0,1-dt*6));
      if(this.flingV.lengthSq()<0.01)this.flingV=null;
    }
    const k=Math.min(this.deathT/0.5,1);
    this.root.quaternion.slerpQuaternions(Q0,this.qTotal,easeOutCubic(k));
    if(this.deathT>3.4){
      if(!this.fading){ this.fading=true; for(const m of this.mats){m.transparent=true;} }
      const op=1-(this.deathT-3.4)/1.1;
      for(const m of this.mats)m.opacity=Math.max(0,op);
      this.pos.y-=dt*0.4;
      if(this.deathT>4.6){
        this.active=false; this.root.visible=false;
        rebuildTargets();
      }
    }
  }
  update(dt){
    if(this.dead){ this.updateDeath(dt); return; }
    const dx=P.pos.x-this.pos.x, dz=P.pos.z-this.pos.z;
    const dist=Math.hypot(dx,dz);
    this.losT-=dt;
    if(this.losT<=0){
      this.losT=0.22+Math.random()*0.12;
      this.hasLOS=checkLOS(this.eyePos(TV1),TV2.copy(camera.position));
    }
    // stuck check
    this.stuckT+=dt;
    if(this.stuckT>1.2){
      if(Math.hypot(this.pos.x-this.lastX,this.pos.z-this.lastZ)<0.15&&this.state==='advance')this.pickCover();
      this.lastX=this.pos.x; this.lastZ=this.pos.z; this.stuckT=0;
    }
    let moving=0;
    let faceYaw=this.yawG.rotation.y;
    if(this.reactT>0)this.reactT-=dt;
    if(this.shotT>0)this.shotT-=dt;
    if(this.state==='advance'){
      let tx,tz;
      if(!this.cover){ this.pickCover(); }
      if(this.cover){ tx=this.cover.x; tz=this.cover.z; }
      else { tx=P.pos.x; tz=P.pos.z; }
      const mdx=tx-this.pos.x, mdz=tz-this.pos.z;
      const md=Math.hypot(mdx,mdz);
      if(this.cover&&md<1.15){
        this.state='combat'; this.peekT=rand(0.3,0.9);
      }else if(!this.cover&&dist<13){
        this.state='combat';
      }else if(md>0.05){
        const sp=dist<12?this.speed+0.6:this.speed;
        this.pos.x+=mdx/md*sp*dt; this.pos.z+=mdz/md*sp*dt;
        moving=1; faceYaw=Math.atan2(-mdx,-mdz);
      }
      if(this.hasLOS&&dist<18){ this.state='combat'; this.cover=null; }
      this.aim=damp(this.aim,this.hasLOS&&dist<20?0.7:0.15,4,dt);
      this.crouch=damp(this.crouch,0,6,dt);
    }else{ // combat
      faceYaw=Math.atan2(-dx,-dz);
      if(!this.cover&&dist>17){ this.state='advance'; this.pickCover(); }
      if(!this.hasLOS){
        this.lostT+=dt;
        this.peeking=false;
        if(this.lostT>2){ this.lostT=0; this.state='advance'; this.pickCover(); }
      }else this.lostT=0;
      if(this.reactT<=0&&!this.peeking&&this.hasLOS){
        this.peekT-=dt;
        if(this.peekT<=0){
          this.peeking=true;
          this.burstLeft=3+(Math.random()*3|0);
          this.shotT=0.42;
        }
      }
      if(this.peeking){
        if(this.shotT<=0&&this.burstLeft>0&&this.hasLOS&&this.reactT<=0&&(S.state==='playing'||S.state==='attract')){
          this.shoot(); this.burstLeft--; this.shotT=0.1+rand(0.03);
        }
        if(this.burstLeft<=0&&this.shotT<-0.45){ this.peeking=false; this.peekT=rand(0.7,1.8); }
      }
      // combat strafe — lateral repositioning between peeks
      this.strafeT-=dt;
      if(this.strafeT<=0){
        this.strafeOn=!this.strafeOn;
        this.strafeT=this.strafeOn?rand(0.7,1.5):rand(0.5,1.1);
        if(Math.random()<0.5)this.strafeDir=-this.strafeDir;
      }
      if(this.strafeOn&&this.hasLOS&&dist>2.2){
        this.pos.x+=(-dz/dist)*this.strafeDir*2.1*dt;
        this.pos.z+=(dx/dist)*this.strafeDir*2.1*dt;
        moving=1;
      }
      this.aim=damp(this.aim,this.hasLOS?1:0.3,6,dt);
      this.crouch=damp(this.crouch,this.peeking?0:1,5,dt);
    }
    // physics
    collideXZ(this.pos,0.45,true);
    this.pos.x=clamp(this.pos.x,-46,46); this.pos.z=clamp(this.pos.z,-46,46);
    // separation
    for(const o of enemies){
      if(o===this||!o.active||o.dead)continue;
      const sx=this.pos.x-o.pos.x, sz=this.pos.z-o.pos.z;
      const sd=Math.hypot(sx,sz);
      if(sd<0.9&&sd>0.001){ this.pos.x+=sx/sd*(0.9-sd)*0.5; this.pos.z+=sz/sd*(0.9-sd)*0.5; }
    }
    // player push
    if(dist<0.85&&dist>0.001){ this.pos.x-=dx/dist*(0.85-dist); this.pos.z-=dz/dist*(0.85-dist); }
    // animation
    this.moveAmt=damp(this.moveAmt,moving,8,dt);
    this.walkPh+=dt*(2.2+this.speed*2.4)*Math.max(this.moveAmt,0.01);
    const sw=Math.sin(this.walkPh)*0.55*this.moveAmt;
    const cr=this.crouch;
    this.legL.rotation.x=sw+cr*1.3;
    this.legR.rotation.x=-sw+cr*1.3;
    this.legL.children[1].rotation.x=Math.max(0,-Math.sin(this.walkPh))*0.85*this.moveAmt-cr*1.45;
    this.legR.children[1].rotation.x=Math.max(0,Math.sin(this.walkPh))*0.85*this.moveAmt-cr*1.45;
    const armAim=-1.15*this.aim+(-0.25+sw*0.35)*(1-this.aim);
    this.armL.rotation.x=damp(this.armL.rotation.x,armAim,8,dt);
    this.armR.rotation.x=damp(this.armR.rotation.x,armAim-0.08,8,dt);
    this.body.position.y=damp(this.body.position.y,-0.26*cr,8,dt);
    // aim pitch at player
    const eyeY=this.pos.y+(this.crouch>0.5?1.05:1.28);
    const pitch=Math.atan2(camera.position.y-eyeY,dist);
    this.gunPivot.rotation.x=lerp(-0.35,pitch,this.aim);
    // face
    let dy=faceYaw-this.yawG.rotation.y;
    dy=Math.atan2(Math.sin(dy),Math.cos(dy));
    this.yawG.rotation.y+=dy*Math.min(1,dt*7);
  }
}
