function groundHeightAt(x,z){
  let h=0;
  for(const c of colliders){
    if(x>c.x1-0.25&&x<c.x2+0.25&&z>c.z1-0.25&&z<c.z2+0.25&&c.h<2.2)h=Math.max(h,c.h);
  }
  return h;
}
function collideXZ(p,r,ignoreHeight){
  for(let it=0;it<2;it++){
    for(const c of colliders){
      if(!ignoreHeight&&P.pos.y>c.h-0.25)continue;
      const cx=clamp(p.x,c.x1,c.x2), cz=clamp(p.z,c.z1,c.z2);
      const dx=p.x-cx, dz=p.z-cz, d2=dx*dx+dz*dz;
      if(d2<r*r){
        if(d2<1e-9){
          const l=p.x-c.x1, rr=c.x2-p.x, t=p.z-c.z1, bb=c.z2-p.z;
          const m=Math.min(l,rr,t,bb);
          if(m===l)p.x=c.x1-r; else if(m===rr)p.x=c.x2+r; else if(m===t)p.z=c.z1-r; else p.z=c.z2+r;
        }else{
          const d=Math.sqrt(d2);
          p.x=cx+dx/d*r; p.z=cz+dz/d*r;
        }
      }
    }
  }
}

function updatePlayer(dt,dtW){
  if(S.state==='dead'){
    P.deathT+=dt;
    return;
  }
  const wishF=(keys['KeyW']?1:0)-(keys['KeyS']?1:0);
  const wishR=(keys['KeyD']?1:0)-(keys['KeyA']?1:0);
  P.crouch=!!(keys['KeyC']||keys['ControlLeft']);
  const fwd=TV1.set(-Math.sin(P.yaw),0,-Math.cos(P.yaw));
  const right=TV2.set(Math.cos(P.yaw),0,-Math.sin(P.yaw));
  const wish=TV3.set(0,0,0).addScaledVector(fwd,wishF).addScaledVector(right,wishR);
  if(wish.lengthSq()>0)wish.normalize();
  const movingF=wishF>0;
  P.sprint=!!(keys['ShiftLeft']&&movingF&&P.grounded&&!P.crouch&&!P.adsHeld&&!P.reloading);
  if(P.trigger)P.sprint=false;
  let speed=P.crouch?2.4:(P.sprint?6.6:4.3);
  if(P.adsT>0.5)speed=Math.min(speed,3.4);
  const acc=P.grounded?16:4;
  P.vel.x=damp(P.vel.x,wish.x*speed,acc,dt);
  P.vel.z=damp(P.vel.z,wish.z*speed,acc,dt);
  if(keys['Space']&&P.grounded){ P.vel.y=5.8; P.grounded=false; sfx.jump(); }
  P.vel.y-=13.5*dt;
  P.pos.addScaledVector(P.vel,dt);
  collideXZ(P.pos,0.45,false);
  P.pos.x=clamp(P.pos.x,-45.5,45.5); P.pos.z=clamp(P.pos.z,-45.5,45.5);
  const gh=groundHeightAt(P.pos.x,P.pos.z);
  if(P.pos.y<=gh){
    if(!P.grounded){
      const iv=-P.vel.y;
      if(iv>3){
        sfx.land(iv);
        dipSpring.vel-=clamp(iv,3,9)*0.05;
        trauma=Math.min(1,trauma+iv*0.012);
        emitDust(TV4.set(P.pos.x,gh+0.05,P.pos.z));
      }
    }
    P.pos.y=gh; P.vel.y=0; P.grounded=true;
  }else P.grounded=P.pos.y-gh<0.02;
  P.speedXZ=Math.hypot(P.vel.x,P.vel.z);
  // headbob + footsteps
  const bobAmt=P.grounded?Math.min(P.speedXZ/4.3,1.4):0;
  P.bobPhase+=dt*(P.sprint?11:8)*Math.min(P.speedXZ/4.3,1.2);
  if(P.grounded&&P.speedXZ>0.5){
    P.stepAcc+=P.speedXZ*dt;
    const stride=P.sprint?2.7:2.1;
    if(P.stepAcc>stride){ P.stepAcc=0; sfx.footstep(P.sprint); }
  }
  P.bobAmt=bobAmt;
  // regen
  P.lastHurt+=dt;
  if(P.lastHurt>4&&P.health<100)P.health=Math.min(100,P.health+14*dt);
}

