function fire(){
  const w=curW();
  w.mag--; P.mag=w.mag;
  P.fireT=60/w.rpm;
  camera.updateMatrixWorld();
  const move=Math.min(P.speedXZ/6,1);
  let spread=(0.0042+P.bloom*0.02+move*0.011+(P.grounded?0:0.02))*w.spreadMul;
  if(P.crouch)spread*=0.85;
  spread*=lerp(1,0.28,P.adsT);
  const dir=TV1.set(0,0,-1).applyQuaternion(camera.quaternion);
  const right=TV2.setFromMatrixColumn(camera.matrixWorld,0);
  const up=TV3.setFromMatrixColumn(camera.matrixWorld,1);
  muzzleWorldPos(TV5);
  playerLight.position.copy(TV5); playerLight.intensity=4*(w.pellets>1?1.8:1);
  vmFlash.visible=true; vmFlash.material.rotation=rand(TAU);
  const fs=rand(w.flashS[0],w.flashS[1]); vmFlash.scale.set(fs*w.flashW,fs,1);
  vmLight.intensity=w.lightI;
  let totDmg=0,totHead=false,dmgAt=null;
  for(let pl=0;pl<w.pellets;pl++){
    const sp=spread+(w.pellets>1?w.pelletSpread:0);
    const pd=TV6.copy(dir).addScaledVector(right,rs(sp)).addScaledVector(up,rs(sp)).normalize();
    shootRay.set(camera.position,pd); shootRay.far=220;
    const hits=shootRay.intersectObjects(shootTargets,false);
    const end=TV4.copy(camera.position).addScaledVector(pd,220);
    let hitEn=null,part=null;
    if(hits.length){
      const h=hits[0];
      end.copy(h.point);
      const ud=h.object.userData;
      if(ud&&ud.en){ hitEn=ud.en; part=ud.part; }
    }
    fireTracer(TV5,end,300);
    if(hitEn){
      const head=part==='head';
      let dmg=head?w.dmgH:part==='limb'?w.dmgL:w.dmgB;
      if(w.pellets>1)dmg*=clamp(1.55-end.distanceTo(camera.position)/18,0.3,1);
      emitBlood(end,dir,head?12:7);
      totDmg+=dmg; totHead=totHead||head;
      if(!dmgAt)dmgAt=TV7.copy(end);
      hitEn.damage(dmg,end,dir,head);
    }else if(hits.length){
      emitSparks(end,6);
      emitDust(end);
      if(w.pellets>1&&pl===0)emitRing(end,rand(0.7,1.0),0.32);
    }
  }
  if(totDmg>0){
    dmgNum(dmgAt,String(Math.round(totDmg)),totHead?'crit':'');
    if(totHead)sfx.hitHead(); else sfx.hitBody();
    hitMarker(false);
  }
  // casing
  TV6.set(0.24*(1-0.6*P.adsT),-0.1,-0.5);
  camera.localToWorld(TV6);
  spawnCasing(TV6,TV2,TV3);
  sfx[w.snd]();
  emitSmoke(TV5,rs(0.25),rand(0.5,0.9),rs(0.25),rand(0.07,0.12),rand(0.5,0.9),0.6,0.58,0.6,0.22);
  if(w.pellets>1){
    for(let i=0;i<2;i++)emitSmoke(TV5,rs(0.4),rand(0.4,0.8),rs(0.4),rand(0.12,0.2),rand(0.8,1.3),0.55,0.52,0.5,0.3);
    fxPulse(0.45);
  }
  P.bloom=Math.min(1,P.bloom+w.kick.bloom);
  const adsR=lerp(1,0.72,P.adsT);
  recPZ.vel+=w.kick.pz*adsR;
  recRX.vel+=w.kick.rx*adsR;
  camPitch.vel+=(w.kick.pitch+P.bloom*0.5)*adsR;
  camYaw.vel+=rs(w.kick.yaw)*adsR;
  fovKick.vel+=w.kick.fk;
  trauma=Math.min(1,trauma+w.kick.tr+(w.pellets>1?0.05:0));
  P.lastShot=S.time;
  if(w.pump)P.pumpSndT=0.22;
  if(w.mag===0)startReload();
}
function updateWeapon(dt,dtW){
  // weapon switch (lower current, swap at midpoint, raise new)
  if(P.switchT>0){
    P.switchT-=dt;
    if(!P.switched&&P.switchT<=WEAPONS[P.wNext].switchT*0.5){
      P.switched=true;
      P.wIdx=P.wNext;
      showWeapon(P.wIdx);
    }
    if(P.switchT<0)P.switchT=0;
  }
  const w=curW();
  // fire
  P.fireT-=dt;
  const canFire=!P.reloading&&P.switchT<=0&&P.sprintT<0.4&&S.state==='playing';
  if(P.trigger&&canFire&&P.fireT<=0){
    if(w.mag>0){
      if(w.auto||!P.semiLock){ fire(); if(!w.auto)P.semiLock=true; }
    }else{ P.fireT=0.25; sfx.dry(); startReload(); }
  }
  if(P.pumpSndT>0){ P.pumpSndT-=dt; if(P.pumpSndT<=0)sfx.pump(); }
  // barrel smoke after burst
  if(S.time-P.lastShot>0.14&&P.lastShot>0&&P.afterShotT<9){
    P.afterShotT=99;
    muzzleWorldPos(TV1);
    for(let i=0;i<3;i++)
      emitSmoke(TV1,rs(0.2),rand(0.5,0.9),rs(0.2),rand(0.1,0.2),rand(0.7,1.2),0.6,0.6,0.62,0.28);
  }
  // bloom decay
  P.bloom=Math.max(0,P.bloom-dt*1.7);
  // ads / sprint blends
  const adsTarget=(P.adsHeld&&!P.sprint&&!P.reloading&&P.switchT<=0&&S.state==='playing')?1:0;
  P.adsT=damp(P.adsT,adsTarget,11,dt);
  if(lensGlass)lensGlass.material.opacity=lerp(0.5,0.88,sstep(0.55,1,P.adsT)); // ADS glass clarifies only after the red dot is fully lit
  P.sprintT=damp(P.sprintT,P.sprint?1:0,9,dt);
  // reload (keyframes scale with per-weapon reload time)
  let tilt=0,magY=0,magRz=0,boltZ=0,pumpZ=0;
  const RT=w.reload,rk=RT/2.2;
  if(P.reloading){
    P.reloadT+=dt;
    const t=P.reloadT;
    tilt=Math.min(sstep(0,0.35*rk,t),1-sstep(RT-0.35*rk,RT,t));
    if(t<0.35*rk){ const k=sstep(0.14*rk,0.35*rk,t); magY=-0.17*k; magRz=0.55*k; }
    else if(t<1.05*rk){ magY=-0.2; magRz=0.62; }
    else if(t<1.3*rk){ const k=sstep(1.05*rk,1.26*rk,t); magY=lerp(-0.2,0,easeOutCubic(k)); magRz=lerp(0.62,0,k); }
    if(t>1.28*rk&&t<1.5*rk)magY=-0.012*(1-sstep(1.28*rk,1.48*rk,t));
    if(t>1.5*rk&&t<1.62*rk)boltZ=0.045*sstep(1.5*rk,1.6*rk,t);
    else if(t>=1.62*rk&&t<1.78*rk)boltZ=0.045*(1-sstep(1.62*rk,1.74*rk,t));
    if(!P.relS[0]&&t>0.3*rk){ P.relS[0]=1; sfx.reloadClack(1); muzzleWorldPos(TV1); dropWorldMag(TV1,TV2.set(0,0,-1).applyQuaternion(camera.quaternion)); }
    if(!P.relS[1]&&t>1.16*rk){ P.relS[1]=1; sfx.reloadClack(2); recPZ.vel+=0.7; recRX.vel+=0.9; }
    if(!P.relS[2]&&t>1.52*rk){ P.relS[2]=1; sfx.reloadClack(3); }
    if(!P.relS[3]&&t>1.74*rk){ P.relS[3]=1; sfx.reloadClack(2); recRX.vel+=0.5; }
    if(t>=RT){
      P.reloading=false;
      w.mag=w.magSize; P.mag=w.mag;
    }
  }
  // shotgun pump cycle
  if(w.pump){
    const pt=S.time-P.lastShot;
    if(pt>0.15&&pt<0.6)pumpZ=Math.sin((pt-0.15)/0.45*Math.PI)*0.05;
  }
  // springs
  swayPX.update(dt); swayPY.update(dt); swayRX.update(dt); swayRY.update(dt); swayRZ.update(dt);
  recPZ.update(dt); recRX.update(dt);
  fovKick.update(dt);
  swayRZ.target=-wishRSteel*0.055;
  // compose viewmodel
  const bobA=(P.bobAmt||0)*(P.grounded?1:0);
  const bobX=Math.cos(P.bobPhase)*0.011*bobA*(1-0.8*P.adsT)*(1-P.sprintT*0.5);
  const bobY=Math.sin(P.bobPhase*2)*0.007*bobA*(1-0.8*P.adsT);
  const breathe=Math.sin(S.time*1.7)*0.0016;
  let swLower=0;
  if(P.switchT>0)swLower=Math.sin(clamp(1-P.switchT/WEAPONS[P.wNext].switchT,0,1)*Math.PI);
  const hx=lerp(w.hipX,0,P.adsT), hy=lerp(-0.2,w.adsY,P.adsT), hz=lerp(-0.5,w.adsZ,P.adsT);
  const swScale=1-0.68*P.adsT;
  vmRig.position.set(
    hx+swayPX.v*swScale+bobX+0.03*P.sprintT+0.018*tilt,
    hy+swayPY.v*swScale+bobY+breathe-0.095*P.sprintT+0.012*tilt-0.26*swLower,
    hz+recPZ.v+0.06*P.sprintT
  );
  w.group.rotation.set(
    swayRX.v*0.5*swScale+recRX.v+0.55*P.sprintT-0.1*tilt+Math.sin(P.bobPhase)*0.008*bobA-0.9*swLower,
    swayRY.v*swScale+0.4*P.sprintT,
    swayRZ.v+0.32*tilt+0.22*P.sprintT
  );
  w.magGroup.position.y=magY;
  w.magGroup.rotation.z=magRz;
  w.boltMesh.position.z=w.boltZ0+boltZ+pumpZ;
  // fov
  const baseFov=75+6*P.sprintT-w.adsZoom*P.adsT-SM.k*5;
  const f=baseFov+fovKick.v;
  if(Math.abs(camera.fov-f)>0.01){ camera.fov=f; camera.updateProjectionMatrix(); }
  // vm flash decay
  if(vmFlash.visible){ vmFlash.userDataT=(vmFlash.userDataT||0)+dt; if(vmFlash.userDataT>0.04){vmFlash.visible=false;vmFlash.userDataT=0;} }
  if(vmLight.intensity>0)vmLight.intensity=Math.max(0,vmLight.intensity-dt*120);
  if(playerLight.intensity>0)playerLight.intensity=Math.max(0,playerLight.intensity-dt*90);
  if(enemyLight.intensity>0)enemyLight.intensity=Math.max(0,enemyLight.intensity-dt*80);
}
let wishRSteel=0;

/* ============================== CAMERA ============================== */
function updateCamera(dt){
  // trauma shake
  trauma=Math.max(0,trauma-dt*1.5);
  const sh=trauma*trauma;
  const t=S.time*33;
  const shY=(Math.sin(t*1.1)+Math.sin(t*2.3)*0.5)*0.012*sh;
  const shX=(Math.sin(t*1.7)+Math.sin(t*2.9)*0.5)*0.012*sh;
  const shR=Math.sin(t*1.3)*0.014*sh;
  dipSpring.update(dt);
  camPitch.update(dt); camYaw.update(dt);
  const crouchEye=P.crouch?1.12:1.66;
  let eyeH=damp(camera.userData.eyeH===undefined?1.66:camera.userData.eyeH,crouchEye,10,dt);
  camera.userData.eyeH=eyeH;
  let camY=P.pos.y+eyeH;
  const bobC=Math.sin(P.bobPhase*2)*0.024*(P.bobAmt||0)*(1-0.6*P.adsT);
  camY+=bobC+dipSpring.v;
  if(S.state==='dead'){
    const k=Math.min(P.deathT/1.2,1);
    camY=lerp(camY,P.pos.y+0.45,easeOutCubic(k));
    camera.rotation.z=lerp(0,0.5,easeOutCubic(k));
  }else{
    camera.rotation.z=shR+Math.sin(P.bobPhase)*0.004*(P.bobAmt||0)-wishRSteel*0.01;
  }
  camera.position.set(P.pos.x,camY,P.pos.z);
  camera.rotation.y=P.yaw+camYaw.v+shY;
  camera.rotation.x=P.pitch+camPitch.v+(S.state==='dead'?lerp(0,-0.15,Math.min(1,P.deathT/1.2)):shX);
  camera.updateMatrixWorld();
}

/* ============================== WAVES ============================== */
function startWave(n){
  S.wave=n;
  S.spawnLeft=Math.min(6+2*n,14);
  S.spawnT=0.6;
  banner('WAVE '+n,'HOSTILES INBOUND — '+S.spawnLeft);
  sfx.waveStart();
  $('waveVal').textContent='WAVE '+n;
}
function aliveCount(){
  let n=0;
  for(const e of enemies)if(e.active&&!e.dead)n++;
  return n;
}
function spawnEnemy(){
  let cands=spawnPts.filter(p=>Math.hypot(p.x-P.pos.x,p.z-P.pos.z)>11);
  if(!cands.length)cands=spawnPts;
  cands.sort((a,b)=>Math.hypot(a.x-P.pos.x,a.z-P.pos.z)-Math.hypot(b.x-P.pos.x,b.z-P.pos.z)); // closest ring first — shorter approach
  const pick=cands[Math.floor(rand(Math.min(5,cands.length)))];
  for(const e of enemies)if(!e.active){ e.spawn(pick.x+rs(1.2),pick.z+rs(1.2)); return; }
}
function updateWaves(dt){
  if(S.state!=='playing'&&S.state!=='attract')return;
  if(S.spawnLeft>0){
    S.spawnT-=dt;
    if(S.spawnT<=0){ S.spawnT=0.55; S.spawnLeft--; spawnEnemy(); $('hostiles').textContent='HOSTILES '+(aliveCount()+S.spawnLeft); }
  }else if(!S.inter&&aliveCount()===0&&S.wave>0){
    S.inter=true; S.interT=3;
    const bonus=250+50*S.wave;
    S.score+=bonus;
    P.health=100;
    banner('WAVE CLEAR','+'+bonus+' — RESUPPLIED');
    sfx.waveClear();
    saveBest(); updateScoreHUD();
  }
  if(S.inter){
    S.interT-=dt;
    if(S.interT<=0){ S.inter=false; startWave(S.wave+1); }
  }
}
