function lockPointer(){
  try{
    const r=canvas.requestPointerLock({unadjustedMovement:true});
    if(r&&r.catch)r.catch(()=>{ try{canvas.requestPointerLock();}catch(e){} });
  }catch(e){ try{canvas.requestPointerLock();}catch(e2){} }
  // fail-safe: if lock never lands (e.g. Chrome's post-Esc cooldown), fall back to pause screen
  setTimeout(()=>{
    if(S.state==='playing'&&document.pointerLockElement!==canvas)pauseGame();
  },450);
}
function showBox(id){
