/* ============================== LAMP FLICKER ============================== */
function updateLamps(dt){
  for(const l of lamps){
    if(!l.flicker)continue;
    l.t+=dt;
    if(l.drop>0){
      l.drop-=dt;
      l.light.intensity=Math.max(0,l.base*Math.random()*0.4);
    }else{
