/* ============================== ADAPTIVE RESOLUTION ============================== */
let fpsAcc=0,fpsN=0,dprCur=MAXDPR,adaptT=0,perfLevel=0,lowT=0,goodT=0;
function perfCapDpr(){ return [MAXDPR,1.25,1.0,0.8][perfLevel]; }
function applyPerf(){
  if(dprCur>perfCapDpr()){ dprCur=perfCapDpr(); renderer.setPixelRatio(dprCur); }
  if(motes)motes.pts.visible=perfLevel<2;
  sizePost();
}
function adapt(dt){
  adaptT+=dt; fpsAcc+=dt; fpsN++;
  if(adaptT<0.6)return;
  const avg=fpsAcc/fpsN;
  fpsAcc=0; fpsN=0; adaptT=0;
  // perf guard: <45fps for ~2s sheds a level; sustained 52fps+ recovers one
  if(avg>0.0222){ lowT+=0.6; goodT=0; }
  else { if(avg<0.019)goodT+=0.6; lowT=Math.max(0,lowT-0.3); }
  if(lowT>2&&perfLevel<3){ perfLevel++; lowT=0; applyPerf(); }
  else if(goodT>4&&perfLevel>0){ perfLevel--; goodT=0; applyPerf(); }
  let d=dprCur;
  if(avg>0.0178&&d>0.66)d=Math.max(0.66,d-0.15);
  else if(avg<0.0138&&d<Math.min(MAXDPR,perfCapDpr()))d=Math.min(perfCapDpr(),d+0.1);
  if(Math.abs(d-dprCur)>0.001){ dprCur=d; renderer.setPixelRatio(d); sizePost(); }
}

