/* ============================== EXPOSURE / LIGHT PARITY (attract -> gameplay) ============================== */
const EXP_ATTRACT=4.9, EXP_GAME=4.2, HEMI_GAME=2.6, SUN_GAME=3.0, LIGHT_RAMP=0.6;
let expCur=EXP_ATTRACT, expFrom=EXP_ATTRACT, expTgt=EXP_ATTRACT, hemiFrom=3.2, sunFrom=3.4, lightT=1;
function beginGameplayLighting(){
  expFrom=expCur; expTgt=EXP_GAME;
  hemiFrom=hemi.intensity; sunFrom=sun.intensity; lightT=0;
}
function updateLightRamp(dt){
  if(lightT>=1)return;
  lightT=Math.min(1,lightT+dt/LIGHT_RAMP);
  const k=sstep(0,1,lightT);
  expCur=lerp(expFrom,expTgt,k);
  renderer.toneMappingExposure=expCur;
  hemi.intensity=lerp(hemiFrom,HEMI_GAME,k);
  sun.intensity=lerp(sunFrom,SUN_GAME,k);
}
/* ============================== GRAPHICS PUSH: POST FX / RINGS / FLASH LIGHTS / MOTES / SLOW-MO ============================== */
let CRT=lsGet('bp_crt','1')!=='0';
let postOK=true,postPulse=0;
function fxPulse(v){ postPulse=Math.min(1.2,Math.max(postPulse,v)); }

/* --- shockwave rings (pooled sprites) --- */
const rings=[];
for(let i=0;i<10;i++){
  const sp=new THREE.Sprite(new THREE.SpriteMaterial({map:texRing,color:0xffc890,transparent:true,blending:THREE.AdditiveBlending,depthWrite:false,fog:false}));
  sp.visible=false; scene.add(sp);
  rings.push({sp,on:false,t:0,dur:0.4,sc:1});
}
function emitRing(p,sc,dur=0.45){
  let r=null;
  for(const k of rings)if(!k.on){r=k;break;}
  if(!r)return;
  r.on=true; r.t=0; r.dur=dur; r.sc=sc;
  r.sp.visible=true; r.sp.position.set(p.x,p.y+0.05,p.z);
  r.sp.material.rotation=rand(TAU); r.sp.material.opacity=0.85;
  r.sp.scale.set(sc,sc,1);
}
function updateRings(dt){
  for(const r of rings){
    if(!r.on)continue;
    r.t+=dt;
    const k=r.t/r.dur;
    if(k>=1){ r.on=false; r.sp.visible=false; continue; }
    const s=r.sc*(0.35+easeOutCubic(k)*2.4);
    r.sp.scale.set(s,s,1);
    r.sp.material.opacity=0.85*(1-k)*(1-k);
  }
}

/* --- pooled flash lights: brief illumination of nearby geometry --- */
const boomLights=[];
for(let i=0;i<3;i++){
  const l=new THREE.PointLight(0xffa050,0,18,2);
  scene.add(l);
  boomLights.push({l,t:0,dur:1,i0:0});
}
function flashLight(p,intensity,dur=0.2){
  let b=boomLights[0];
  for(const k of boomLights)if(k.t<b.t)b=k;
  b.t=b.dur=dur; b.i0=intensity;
  b.l.position.set(p.x,p.y+0.25,p.z);
  b.l.intensity=intensity;
}
function updateBoomLights(dt){
  for(const b of boomLights){
    if(b.t<=0)continue;
    b.t-=dt;
    if(b.t<=0){ b.l.intensity=0; continue; }
    b.l.intensity=b.i0*(b.t/b.dur);
  }
}

/* --- drifting dust motes (wrap around player, dilate in slow-mo) --- */
const motes=(()=>{
  const N=230;
  const g=new THREE.BufferGeometry();
  const pos=new Float32Array(N*3), col=new Float32Array(N*3), siz=new Float32Array(N), alp=new Float32Array(N);
  const vel=new Float32Array(N*3);
  for(let i=0;i<N;i++){
    pos[i*3]=rand(-32,32); pos[i*3+1]=rand(0.2,7.5); pos[i*3+2]=rand(-32,32);
    const a=rand(TAU), s=rand(0.06,0.3);
    vel[i*3]=Math.cos(a)*s; vel[i*3+1]=rand(-0.03,0.09); vel[i*3+2]=Math.sin(a)*s;
    siz[i]=rand(0.018,0.05); alp[i]=rand(0.05,0.16);
    const warm=Math.random()<0.7;
    col[i*3]=1; col[i*3+1]=warm?0.85:0.8; col[i*3+2]=warm?0.62:0.9;
  }
  g.setAttribute('position',new THREE.BufferAttribute(pos,3));
  g.setAttribute('aColor',new THREE.BufferAttribute(col,3));
  g.setAttribute('aSize',new THREE.BufferAttribute(siz,1));
  g.setAttribute('aAlpha',new THREE.BufferAttribute(alp,1));
  const m=new THREE.ShaderMaterial({transparent:true,depthWrite:false,blending:THREE.AdditiveBlending,vertexShader:P_VS,fragmentShader:P_FS});
  const pts=new THREE.Points(g,m); pts.frustumCulled=false; scene.add(pts);
  return {pts,pos,vel,N,
    update(dt,t){
      const cx=P.pos.x, cz=P.pos.z, p=this.pos;
      for(let i=0;i<this.N;i++){
        const k3=i*3;
        p[k3]+=(this.vel[k3]+Math.sin(t*0.6+i*1.7)*0.06)*dt;
        p[k3+1]+=this.vel[k3+1]*dt+Math.sin(t*0.9+i)*0.02*dt;
        p[k3+2]+=(this.vel[k3+2]+Math.cos(t*0.5+i*2.3)*0.06)*dt;
        if(p[k3]<cx-33)p[k3]+=66; else if(p[k3]>cx+33)p[k3]-=66;
        if(p[k3+2]<cz-33)p[k3+2]+=66; else if(p[k3+2]>cz+33)p[k3+2]-=66;
        if(p[k3+1]<0.1)p[k3+1]=7.5; else if(p[k3+1]>7.6)p[k3+1]=0.1;
      }
      g.attributes.position.needsUpdate=true;
    }};
})();

function updateMotes(dt){ motes.update(dt,S.time); }
/* --- slow-mo (hold Q — extends the S.slowT dilation system) --- */
const SM={charge:1,active:false,k:0,lock:false};
let smDbgShown=false;
function smRelease(){ for(const k in keys)keys[k]=false; if(SM.active){ SM.active=false; sfx.whoosh(false); } sfx.setSlow(0); }
function updateSlowmo(dt){
  const want=!!keys['KeyQ']&&S.state==='playing'&&!SM.lock&&SM.charge>0.001;
  if(want&&!SM.active){ SM.active=true; sfx.whoosh(true); }
  else if(!want&&SM.active){ SM.active=false; sfx.whoosh(false); }
  if(SM.active){
    SM.charge-=dt/4;
    if(SM.charge<=0){ SM.charge=0; SM.active=false; SM.lock=true; sfx.whoosh(false); }
  }else{
    SM.charge=Math.min(1,SM.charge+dt/6);
    if(SM.lock&&SM.charge>0.25)SM.lock=false;
  }
  SM.k=damp(SM.k,SM.active?1:0,12,dt);
  if(!SM.active&&SM.k<0.01)SM.k=0;
  sfx.setSlow(SM.k);
  const el=$('smWrap');
  el.style.opacity=(S.state==='playing'||S.state==='dead')?'1':'0';
  el.classList.toggle('on',SM.active);
  el.classList.toggle('lock',SM.lock);
  $('smFill').style.width=(SM.charge*100).toFixed(1)+'%';
  $('smNum').textContent=String(Math.round(SM.charge*100));
  if(window.__SM_DEBUG){
    smDbgShown=true;
    const tsD=S.hitstopT>0?Math.min(S.hitstopS,S.slowT>0?0.3:1):Math.min(S.slowT>0?0.3:1,SM.k>0.002?lerp(1,0.28,SM.k):1);
    const d=$('smDbg');
    d.style.display='block';
    d.textContent='SM active='+(SM.active?1:0)+' charge='+SM.charge.toFixed(3)+' k='+SM.k.toFixed(3)+' ts='+tsD.toFixed(3);
  }else if(smDbgShown){
    smDbgShown=false;
    $('smDbg').style.display='none';
  }
}

/* --- hand-rolled composer: HDR scene RT -> bloom mips -> composite --- */
const mkRT=()=>new THREE.WebGLRenderTarget(2,2,{type:THREE.HalfFloatType,depthBuffer:false,stencilBuffer:false});
const rtScene=new THREE.WebGLRenderTarget(2,2,{type:THREE.HalfFloatType,depthBuffer:true,stencilBuffer:false,samples:4});
const rtBright=mkRT(),rtBlurA=mkRT(),rtBlurB=mkRT(),rtB2=mkRT(),rtBlur2A=mkRT(),rtBlur2B=mkRT();
const FS_VS=`varying vec2 vUv; void main(){ vUv=position.xy*0.5+0.5; gl_Position=vec4(position.xy,0.0,1.0); }`;
const preFS=`uniform sampler2D tDiffuse; varying vec2 vUv;
void main(){
  vec4 c=texture2D(tDiffuse,vUv);
  float l=dot(c.rgb,vec3(0.2126,0.7152,0.0722));
  gl_FragColor=vec4(c.rgb*smoothstep(0.55,1.05,l),1.0);
}`;
const blurFS=`uniform sampler2D tDiffuse; uniform vec2 uDir; uniform vec2 uTexel; varying vec2 vUv;
void main(){
  vec2 o1=uDir*uTexel*1.38461538, o2=uDir*uTexel*3.23076923;
  vec4 c=texture2D(tDiffuse,vUv)*0.22702703;
  c+=(texture2D(tDiffuse,vUv+o1)+texture2D(tDiffuse,vUv-o1))*0.31621622;
  c+=(texture2D(tDiffuse,vUv+o2)+texture2D(tDiffuse,vUv-o2))*0.07027027;
  gl_FragColor=c;
}`;
const copyFS=`uniform sampler2D tDiffuse; varying vec2 vUv; void main(){ gl_FragColor=texture2D(tDiffuse,vUv); }`;
const postFS=`uniform sampler2D tScene; uniform sampler2D tB1; uniform sampler2D tB2;
uniform float uTime,uExp,uB1,uB2,uCA,uVig,uSlow,uGrain,uScan;
uniform vec2 uRes;
varying vec2 vUv;
float hash(vec2 p){ p=fract(p*vec2(123.34,456.21)); p+=dot(p,p+45.32); return fract(p.x*p.y); }
vec3 aces(vec3 x){ return clamp(x*(2.51*x+0.03)/(x*(2.43*x+0.59)+0.14),0.0,1.0); }
vec3 srgb(vec3 c){ return mix(c*12.92,1.055*pow(max(c,vec3(0.0031308)),vec3(0.4166667))-0.055,step(vec3(0.0031308),c)); }
void main(){
  vec2 d=vUv-0.5;
  float r2=dot(d,d);
  vec2 off=d*(uCA*r2*2.4);
  vec3 col;
  col.r=texture2D(tScene,vUv+off).r;
  col.g=texture2D(tScene,vUv).g;
  col.b=texture2D(tScene,vUv-off).b;
  if(uB1>0.001)col+=texture2D(tB1,vUv).rgb*uB1;
  if(uB2>0.001)col+=texture2D(tB2,vUv).rgb*uB2;
  col=aces(col*uExp);
  col=mix(col,col*vec3(0.80,0.97,1.18)+vec3(0.0,0.012,0.05),uSlow*0.38);
  float lum=dot(col,vec3(0.2126,0.7152,0.0722));
  vec3 stTone=mix(vec3(0.55,0.85,1.0),vec3(1.0,0.72,0.35),clamp(lum*1.4,0.0,1.0));
  col=mix(col,col*stTone,uSlow*0.2);
  col*=1.0-uVig*smoothstep(0.10,0.92,r2*1.9);
  col+=(hash(vUv*uRes*0.35+fract(uTime*7.13)*vec2(37.0,17.0))-0.5)*uGrain;
  col*=1.0-uScan*0.5*(0.5+0.5*sin(vUv.y*uRes.y*3.14159));
  gl_FragColor=vec4(srgb(max(col,vec3(0.0))),1.0);
}`;
const postCam=new THREE.OrthographicCamera(-1,1,1,-1,0,1);
const postScene=new THREE.Scene();
const fsGeo=new THREE.BufferGeometry();
fsGeo.setAttribute('position',new THREE.BufferAttribute(new Float32Array([-1,-1,0,3,-1,0,-1,3,0]),3));
const fsMat=(fs,uniforms)=>new THREE.ShaderMaterial({vertexShader:FS_VS,fragmentShader:fs,uniforms,depthTest:false,depthWrite:false});
const matPre=fsMat(preFS,{tDiffuse:{value:null}});
const matBlur=fsMat(blurFS,{tDiffuse:{value:null},uDir:{value:new THREE.Vector2(1,0)},uTexel:{value:new THREE.Vector2(0.5,0.5)}});
const matCopy=fsMat(copyFS,{tDiffuse:{value:null}});
const matPost=fsMat(postFS,{
  tScene:{value:rtScene.texture},tB1:{value:rtBlurB.texture},tB2:{value:rtBlur2B.texture},
  uTime:{value:0},uExp:{value:EXP_ATTRACT},uB1:{value:0.65},uB2:{value:0.8},
  uCA:{value:0.0012},uVig:{value:0.18},uSlow:{value:0},uGrain:{value:0.04},uScan:{value:0},
  uRes:{value:new THREE.Vector2(2,2)}
});
const fsMesh=new THREE.Mesh(fsGeo,matPre); fsMesh.frustumCulled=false; postScene.add(fsMesh);
function blit(mat,rt){ fsMesh.material=mat; renderer.setRenderTarget(rt); renderer.render(postScene,postCam); }
const _ds=new THREE.Vector2();
function sizePost(){
  renderer.getDrawingBufferSize(_ds);
  const w=Math.max(2,_ds.x|0), h=Math.max(2,_ds.y|0);
  rtScene.setSize(w,h);
  const bw=Math.max(2,w>>1), bh=Math.max(2,h>>1);
  rtBright.setSize(bw,bh); rtBlurA.setSize(bw,bh); rtBlurB.setSize(bw,bh);
  const qw=Math.max(2,w>>2), qh=Math.max(2,h>>2);
  rtB2.setSize(qw,qh); rtBlur2A.setSize(qw,qh); rtBlur2B.setSize(qw,qh);
  matBlur.uniforms.uTexel.value.set(1/bw,1/bh);
  matPost.uniforms.uRes.value.set(w,h);
}
function renderPost(dt){
  postPulse=Math.max(0,postPulse-dt*2.4);
  const u=matPost.uniforms;
  u.uTime.value=performance.now()*0.001;
  u.uExp.value=expCur;
  u.uSlow.value=SM.k;
  u.uVig.value=0.18+SM.k*0.22+postPulse*0.16;
  u.uCA.value=0.0012+SM.k*0.0032+postPulse*0.006;
  u.uScan.value=CRT?0.055:0;
  if(perfLevel<2){
    matPre.uniforms.tDiffuse.value=rtScene.texture;
    blit(matPre,rtBright);
    matBlur.uniforms.tDiffuse.value=rtBright.texture;
    matBlur.uniforms.uDir.value.set(1,0);
    blit(matBlur,rtBlurA);
    matBlur.uniforms.tDiffuse.value=rtBlurA.texture;
    matBlur.uniforms.uDir.value.set(0,1);
    blit(matBlur,rtBlurB);
    if(perfLevel<1){
      matCopy.uniforms.tDiffuse.value=rtBlurB.texture;
      blit(matCopy,rtB2);
      matBlur.uniforms.tDiffuse.value=rtB2.texture;
      matBlur.uniforms.uDir.value.set(1,0);
      blit(matBlur,rtBlur2A);
      matBlur.uniforms.tDiffuse.value=rtBlur2A.texture;
      matBlur.uniforms.uDir.value.set(0,1);
      blit(matBlur,rtBlur2B);
    }
  }
  u.uB1.value=perfLevel<2?0.65:0;
  u.uB2.value=perfLevel<1?0.8:0;
  fsMesh.material=matPost;
  renderer.setRenderTarget(null);
  renderer.render(postScene,postCam);
}
try{
  sizePost();
  for(const rt of [rtBright,rtBlurA,rtBlurB,rtB2,rtBlur2A,rtBlur2B]){ renderer.setRenderTarget(rt); renderer.clear(); }
  renderer.setRenderTarget(null);
}catch(e){ postOK=false; renderer.toneMapping=THREE.ACESFilmicToneMapping; console.error('post init failed',e); }

/* ============================== ATTRACT MODE ============================== */
function updateAttractCamera(dt){
  S.attractT=(S.attractT||0)+dt;
  const t=S.attractT, a=t*0.075, r=15.5+Math.sin(t*0.043)*4.5;
  camera.position.set(Math.cos(a)*r,2.6+Math.sin(t*0.057)*1.2,Math.sin(a)*r);
  let best=null,bd=1e9;
  for(const e of enemies){ if(!e.active||e.dead)continue; const d=e.pos.distanceTo(camera.position); if(d<bd){bd=d;best=e;} }
  S.lookX=damp(S.lookX||0,best?best.pos.x:0,0.8,dt);
  S.lookZ=damp(S.lookZ||0,best?best.pos.z:0,0.8,dt);
  camera.lookAt(S.lookX,3.4,S.lookZ);
  camera.rotation.z+=Math.sin(t*0.1)*0.008;
  P.pos.x=camera.position.x; P.pos.z=camera.position.z; P.pos.y=0;
  P.yaw=camera.rotation.y; P.pitch=camera.rotation.x;
  camera.updateMatrixWorld();
}
function updateAttract(dt){
  updateAttractCamera(dt);
  for(const e of enemies)if(e.active)e.update(dt);
  updateTracers(dt); updateFlashes(dt);
  pUpdate(sparks,dt); pUpdate(puffs,dt);
  updateLamps(dt); updateDmgNums(dt);
  updateMotes(dt); updateRings(dt); updateBoomLights(dt);
  playerLight.intensity=Math.max(0,playerLight.intensity-dt*90);
  enemyLight.intensity=Math.max(0,enemyLight.intensity-dt*80);
  updateHUD(dt);
}
function startFromAttract(){
  sfx.init(); sfx.resume();
  const cx=clamp(camera.position.x,-44,44), cz=clamp(camera.position.z,-44,44);
  const cy=camera.rotation.y, cp=camera.rotation.x;
  resetRun();
  P.pos.set(cx,groundHeightAt(cx,cz),cz);
  P.yaw=cy; P.pitch=clamp(cp,-1.2,1.2);
  S.state='playing';
  beginGameplayLighting();
  $('attractCta').classList.add('hidden');
  $('godRow').classList.add('hidden');
  lockPointer();
}
addEventListener('click',()=>{ if(S.state==='attract')startFromAttract(); });

/* ============================== MAIN LOOP ============================== */
let last=performance.now();
function frame(now){
  requestAnimationFrame(frame);
  let dt=(now-last)/1000; last=now;
  if(dt>0.1)dt=0.1;
  const playing=S.state==='playing'||S.state==='dead';
  if(playing){
    updateSlowmo(dt);
    let ts=1;
    if(S.hitstopT>0){ ts=S.hitstopS; S.hitstopT-=dt; }
    if(S.slowT>0){ ts=Math.min(ts,0.3); S.slowT-=dt; }
    if(SM.k>0.002)ts=Math.min(ts,lerp(1,0.28,SM.k));
    const dtW=dt*ts;
    // strafe lean input
    wishRSteel=(keys['KeyD']?1:0)-(keys['KeyA']?1:0);
    updatePlayer(dt,dtW);
    updateWeapon(dt,dtW);
    updateWaves(dtW);
    for(const e of enemies)if(e.active)e.update(dtW);
    updateTracers(dtW);
    updateCasings(dtW);
    updateWorldMags(dtW);
    updateFlashes(dtW);
    pUpdate(sparks,dtW); pUpdate(puffs,dtW);
    updateMotes(dtW); updateRings(dtW); updateBoomLights(dtW);
    updateDmgNums(dtW);
    updateLamps(dtW);
    updateHUD(dt);
    updateCamera(dt);
  }else if(S.state==='attract'){
    S.time+=dt;
    updateAttract(dt);
  }else if(S.state==='menu'){
    camera.position.set(0,2.2,26);
    camera.rotation.order='YXZ';
    camera.rotation.y=Math.sin(now*0.00012)*0.06;
    camera.rotation.x=-0.04;
    camera.updateMatrixWorld();
  }
  updateLightRamp(dt);
  adapt(dt);
  if(postOK){
    renderer.setRenderTarget(rtScene);
    renderer.clear();
    renderer.render(scene,camera);
    if(S.state==='playing'||S.state==='paused'){
      renderer.clearDepth();
      renderer.render(vmScene,vmCam);
    }
    renderPost(dt);
  }else{
    renderer.clear();
    renderer.render(scene,camera);
    if(S.state==='playing'||S.state==='paused'){
      renderer.clearDepth();
      renderer.render(vmScene,vmCam);
    }
  }
}
